import React, { useState, useEffect } from 'react';

// Import 4 màn hình con từ thư mục components của bạn
import MovieList from './components/MovieList';
import ShowtimeScreen from './components/ShowtimeScreen';
import SeatScreen from './components/SeatScreen';
import AuthScreen from './components/AuthScreen';

function App() {
  const [movies, setMovies] = useState([]);
  const [showtimes, setShowtimes] = useState([]);
  const [seats, setSeats] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  const [currentScreen, setCurrentScreen] = useState('movie-list');
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [selectedShowtime, setSelectedShowtime] = useState(null);

  useEffect(() => {
    // Kết nối đến json-server cổng 5000 ổn định
    fetch('http://localhost:5000/db')
      .then((res) => {
        if (!res.ok) throw new Error("Không thể kết nối cổng dữ liệu!");
        return res.json();
      })
      .then((data) => {
        setMovies(data.movies || []);
        setShowtimes(data.showtimes || []);
        setSeats(data.seats || []);
        setBookings(data.bookings || []);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Lỗi nạp dữ liệu từ json-server:", err);
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <div className="d-flex justify-content-center align-items-center min-vh-100" style={{ backgroundColor: '#f0f9ff' }}>
        <div className="text-center p-5 bg-white rounded-4 shadow-sm">
          <div className="spinner-border text-info mb-3" style={{ width: '3rem', height: '3rem' }} role="status"></div>
          <h5 className="fw-bold text-secondary text-uppercase">Đang nạp dữ liệu rạp phim...</h5>
        </div>
      </div>
    );
  }

  return (
    <div className="min-vh-100 py-4" style={{ backgroundColor: '#f0f9ff', minHeight: '100vh' }}>
      
      {/* 🌟 ĐÃ XÓA TOÀN BỘ KHỐI <nav> BỊ LỖI Ở ĐÂY ĐỂ GIAO DIỆN GỌN GÀNG */}

      {/* KHU VỰC HIỂN THỊ NỘI DUNG CHÍNH */}
      <div className="container">
        
        {/* Thanh thông báo nhỏ gọn khi đang chọn phim (chỉ hiện khi rời màn hình chính) */}
        {selectedMovie && currentScreen !== 'movie-list' && (
          <div className="alert alert-info border-0 shadow-sm mb-4 bg-white d-flex justify-content-between align-items-center rounded-3 animate__animated animate__fadeIn">
            <span>📍 Bạn đang chọn phim: <strong className="text-primary">{selectedMovie.title}</strong></span>
            <button className="btn btn-sm btn-outline-secondary rounded-pill px-3" onClick={() => setCurrentScreen('movie-list')}>Đổi phim</button>
          </div>
        )}

        {/* Khung nền trắng bo tròn chứa toàn bộ app */}
        <div className="bg-white p-4 rounded-4 shadow-sm">
          {currentScreen === 'movie-list' && (
            <MovieList 
              movies={movies} 
              showtimes={showtimes}
              onSelectMovie={(movie) => { 
                setSelectedMovie(movie); 
                setCurrentScreen('showtime-list'); 
              }}
              onGoToAuth={() => setCurrentScreen('auth')}
            />
          )}

          {currentScreen === 'showtime-list' && (
            <ShowtimeScreen 
              movie={selectedMovie} 
              showtimes={showtimes} 
              onSelectShowtime={(st) => { 
                setSelectedShowtime(st); 
                setCurrentScreen('seat-plan'); 
              }}
              onBack={() => setCurrentScreen('movie-list')} 
            />
          )}

          {currentScreen === 'seat-plan' && (
            <SeatScreen 
              showtime={selectedShowtime} 
              movie={selectedMovie}
              seats={seats}
              bookings={bookings}
              onBookingSuccess={(newBookings) => setBookings([...bookings, ...newBookings])}
              onBack={() => setCurrentScreen('showtime-list')}
            />
          )}

          {currentScreen === 'auth' && (
            <AuthScreen onBack={() => setCurrentScreen('movie-list')} />
          )}
        </div>

      </div>
    </div>
  );
}

export default App;
